const $=id=>document.getElementById(id);
const dashboardRows=['Keyin','Net','Recruitment:','NAHP','AHP','Total HP','T/O','SHI Group','SHI Personal','WS Player','Target Collection','Actual Collection'];
const hpRows=['Keyin','Net','Recruitment:','NAHP','AHP','Total HP','T/O','SHI Personal','WS Player','Target Collection','Actual Collection'];
let months=[...Array(6)].map((_,i)=>({label:['December','January','February','March','April','May'][i],key:`month-${2026+(i>0?1:0)}-${String(i===0?12:i).padStart(2,'0')}`}));
const totals=[['Recruitment','Recruitment:'],['NAHP','NAHP'],['AHP','AHP'],['Total HP','Total HP'],['Key in','Keyin'],['Net','Net']];
let dashboard={},hps=new Map(),selectedCode='',user=null,canManage=false,canEditHp=false,saveTimer,refreshTimer;
function message(id,value='',kind=''){const el=$(id);el.textContent=value;el.className=`message ${kind}`}
function number(value){const n=Number(String(value??'').replaceAll(',','').trim());return Number.isFinite(n)?n:0}
function shi(actual,target){return target>0?`${(actual/target*100).toFixed(1)}%`:'—'}
function collections(values,prefix,labels){return{target:number(values[`${prefix}-${labels.indexOf('Target Collection')}-target`]),actual:number(values[`${prefix}-${labels.indexOf('Actual Collection')}-actual`])}}
function groupShi(){let target=0,actual=0;for(const hp of hps.values()){const amount=collections(hp.metrics,'hp',hpRows);target+=amount.target;actual+=amount.actual}return shi(actual,target)}
function makeCell(text,key,editable,save){const td=document.createElement('td');td.textContent=text;td.contentEditable=editable?'true':'false';if(editable)td.addEventListener('blur',()=>save(key,td.textContent.trim()));return td}
function table(target,labels,values,prefix,editable,save,hiddenRows=[]){const body=$(target),amount=collections(values,prefix,labels);body.replaceChildren();labels.forEach((name,i)=>{if(hiddenRows.includes(i))return;const tr=document.createElement('tr'),calculated=name==='SHI Personal'||name==='SHI Group';for(const [field,fallback] of [['label',name],['target','—'],['actual','—']]){const key=`${prefix}-${i}-${field}`,allowed=!calculated&&!(name==='Target Collection'&&field!=='target')&&!(name==='Actual Collection'&&field!=='actual');let value=values[key]??fallback;if(calculated)value=field==='label'?name:field==='actual'?(name==='SHI Group'?groupShi():shi(amount.actual,amount.target)):'—';if(name==='Target Collection'&&field==='actual'||name==='Actual Collection'&&field==='target')value='—';tr.append(makeCell(value,key,editable&&allowed,save))}body.append(tr)})}
async function api(action,details={}){const response=await fetch('/.netlify/functions/api',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:JSON.stringify({action,...details})});const result=await response.json();if(!response.ok)throw new Error(result.error||'Request failed');return result}
async function saveDashboard(key,value){dashboard[key]=value;renderDashboard();try{await api('updateDashboard',{key,value})}catch(error){message('authMessage',error.message,'error')}}
async function saveHp(key,value){if(!selectedCode||!canEditHp)return;const current=hps.get(selectedCode);if(!current)return;try{await api('updateHp',{code:selectedCode,key,value});current.metrics={...current.metrics,[key]:value};renderScoreboard();renderDashboard();renderHp()}catch(error){message('hpMessage',error.message,'error')}}
function renderDashboard(){table('scoreTable',dashboardRows,dashboard,'score',canManage,saveDashboard);$('monthlyPlan').replaceChildren();months.forEach((month,i)=>{const box=document.createElement('div'),label=document.createElement('b'),content=document.createElement('span');box.className='month';label.textContent=month.label;content.textContent=dashboard[month.key]??dashboard[`month-${i}`]??'Add monthly focus';content.contentEditable=canManage?'true':'false';content.dataset.editable=String(canManage);if(canManage)content.addEventListener('blur',()=>saveDashboard(month.key,content.textContent.trim()));box.append(label,content);$('monthlyPlan').append(box)});$('editStatus').textContent=canManage?'Editing enabled':'View only'}
function renderScoreboard(){const board=$('scoreboard');board.replaceChildren();for(const [title,rowName] of totals){const i=hpRows.indexOf(rowName),sum=[...hps.values()].reduce((total,hp)=>total+(hp.hidden_rows?.includes(i)?0:number(hp.metrics[`hp-${i}-actual`])),0),card=document.createElement('div'),label=document.createElement('small'),value=document.createElement('strong');card.className='stat';label.textContent=title==='Total HP'?title:`Total ${title}`;value.textContent=new Intl.NumberFormat('en-MY',{maximumFractionDigits:2}).format(sum);card.append(label,value);board.append(card)}}
function renderHpSelect(){const select=$('hpSelect'),previous=selectedCode;select.replaceChildren();if(!hps.size){select.add(new Option('No HP accounts yet',''));selectedCode=''}else{for(const [code,hp] of [...hps].sort((a,b)=>a[0].localeCompare(b[0])))select.add(new Option(`${code} · ${hp.name}`,code));selectedCode=hps.has(previous)?previous:select.options[0].value;select.value=selectedCode}renderHp()}
function renderHp(){const hp=hps.get(selectedCode);canEditHp=!!user&&(canManage||hp?.owner_id===user.id||hp?.parent_id===user.id);$('hpIdentity').textContent=hp?`${selectedCode} · ${hp.name}`:'Register the first HP to start tracking.';table('hpTable',hpRows,hp?.metrics||{},'hp',canEditHp,saveHp,hp?.hidden_rows||[]);const controls=$('hpRowControls'),toggles=$('hpRowToggles');controls.classList.toggle('hidden',!canManage||!hp);toggles.replaceChildren();if(canManage&&hp)for(const i of [2,3,4,5,6,8]){const label=document.createElement('label'),input=document.createElement('input');label.className='row-toggle';input.type='checkbox';input.checked=!(hp.hidden_rows||[]).includes(i);input.addEventListener('change',async()=>{const hidden=new Set(hp.hidden_rows||[]);if(input.checked)hidden.delete(i);else hidden.add(i);try{await api('setHpRows',{code:selectedCode,hiddenRows:[...hidden]});hp.hidden_rows=[...hidden];renderHp();renderScoreboard();message('hpMessage',`${hpRows[i]} ${input.checked?'added':'removed'} for ${hp.code}.`,'success')}catch(error){input.checked=!input.checked;message('hpMessage',error.message,'error')}});label.append(input,document.createTextNode(hpRows[i]));toggles.append(label)}}
function setTimeline(start,end){const first=new Date(`${start.slice(0,7)}-01T00:00:00Z`),last=new Date(`${end.slice(0,7)}-01T00:00:00Z`),list=[];for(let date=new Date(first),i=0;date<=last&&i<25;date.setUTCMonth(date.getUTCMonth()+1),i++){list.push({key:`month-${date.toISOString().slice(0,7)}`,label:new Intl.DateTimeFormat('en-GB',{month:'long',year:'numeric',timeZone:'UTC'}).format(date)})}months=list;$('timelineLabel').textContent=`${months[0]?.label||''} to ${months.at(-1)?.label||''}`;renderDashboard()}
async function refresh(){if(!user)return;try{const data=await api('state');dashboard=data.dashboard||{};hps=new Map(data.hps.map(hp=>[hp.code,hp]));window.reportHistory=data.reports||[];$('periodEnd').value=data.settings.period_end;$('periodEnd').min=data.settings.period_start;$('timelineStart').value=data.settings.timeline_start;$('timelineEnd').value=data.settings.timeline_end;setTimeline(data.settings.timeline_start,data.settings.timeline_end);renderHpSelect();renderScoreboard();const box=$('reportHistory');box.replaceChildren();for(const report of window.reportHistory){const line=document.createElement('p');line.textContent=`${report.period_start} to ${report.period_end} · ${report.hp_values?.length||0} HPs`;box.append(line)}}catch(error){message('authMessage',error.message,'error')}}
function showSession(current,needsSetup=false){user=current;canManage=!!current&&['admin','manager'].includes(current.role);$('setup').classList.toggle('hidden',!needsSetup);$('login').classList.toggle('hidden',!!current||needsSetup);$('session').classList.toggle('hidden',!current);$('accounts').classList.toggle('hidden',!current);$('adminControls').classList.toggle('hidden',current?.role!=='admin');$('reports').classList.toggle('hidden',!current);for(const id of ['periodEnd','savePeriodEnd','timelineStart','timelineEnd','saveTimeline'])$(id).disabled=!canManage;$('newRole').disabled=current?.role!=='admin';if(current?.role!=='admin')$('newRole').value='hp';$('userLabel').textContent=current?`${current.username} · ${current.role==='admin'?'Admin':current.role==='manager'?'Team manager':'HP'}`:'';clearInterval(refreshTimer);if(current){refresh();if(current.role==='admin')loadAdminUsers();refreshTimer=setInterval(refresh,15000)}else{dashboard={};hps.clear();window.reportHistory=[];renderDashboard();renderHpSelect();renderScoreboard()}}
async function loadAdminUsers(){if(user?.role!=='admin')return;try{const {users}=await api('listUsers'),box=$('userList');box.replaceChildren();for(const item of users){const row=document.createElement('div'),label=document.createElement('span'),input=document.createElement('input'),reset=document.createElement('button'),remove=document.createElement('button');row.className='controls';label.textContent=`${item.username} · ${item.name} · ${item.role} · Last sign-in: ${item.last_sign_in_at?new Date(item.last_sign_in_at).toLocaleDateString():'Never'}`;input.type='password';input.placeholder='New password (12+ characters)';input.autocomplete='new-password';reset.textContent='Set password';reset.addEventListener('click',async()=>{try{await api('setPassword',{userId:item.id,password:input.value});input.value='';message('adminMessage',`Password changed for ${item.username}.`,'success');if(item.id===user.id)showSession(null)}catch(error){message('adminMessage',error.message,'error')}});remove.textContent='Delete inactive login';remove.className='ghost';const inactive=!item.last_sign_in_at||Date.now()-new Date(item.last_sign_in_at).getTime()>=90*86400000;remove.disabled=!inactive||item.role!=='hp';remove.addEventListener('click',async()=>{if(!confirm(`Delete ${item.username}'s login? Their HP results will stay saved.`))return;try{await api('deleteUser',{userId:item.id});message('adminMessage',`Login ${item.username} deleted.`,'success');await loadAdminUsers();await refresh()}catch(error){message('adminMessage',error.message,'error')}});row.append(label,input,reset,remove);box.append(row)}}catch(error){message('adminMessage',error.message,'error')}}
$('hpSelect').addEventListener('change',e=>{selectedCode=e.target.value;renderHp()});
$('signIn').addEventListener('click',async()=>{try{const result=await api('login',{username:$('username').value.trim().toLowerCase(),password:$('password').value});$('password').value='';showSession(result.user);message('authMessage','Signed in.','success')}catch(error){message('authMessage',error.message,'error')}});
$('setupAdmin').addEventListener('click',async()=>{try{await api('bootstrap',{setupCode:$('setupCode').value,password:$('setupPassword').value});$('setupCode').value=$('setupPassword').value='';showSession(null);message('authMessage','Admin created. Sign in as admin.','success')}catch(error){message('setupMessage',error.message,'error')}});
$('signOut').addEventListener('click',async()=>{await api('logout').catch(()=>{});showSession(null)});
$('createAccount').addEventListener('click',async()=>{const username=$('newCode').value.trim().toLowerCase(),name=$('newName').value.trim(),password=$('newPassword').value,role=$('newRole').value;const button=$('createAccount');button.disabled=true;try{await api('createUser',{username,name,password,role});message('accountMessage',`${username} created. Share the username and password privately.`,'success');$('newCode').value=$('newName').value=$('newPassword').value='';await refresh();if(user.role==='admin')await loadAdminUsers()}catch(error){message('accountMessage',error.message,'error')}button.disabled=false});
$('saveTimeline').addEventListener('click',async()=>{try{await api('settings',{timeline_start:$('timelineStart').value,timeline_end:$('timelineEnd').value});await refresh();message('reportMessage','Timeline saved.','success')}catch(error){message('reportMessage',error.message,'error')}});
$('savePeriodEnd').addEventListener('click',async()=>{try{await api('settings',{period_end:$('periodEnd').value});await refresh();message('reportMessage','Month-end date saved.','success')}catch(error){message('reportMessage',error.message,'error')}});
function csvCell(v){return `"${String(v??'').replaceAll('"','""')}"`}
function reportRows(){const lines=[['Period','HP code','HP name','Row','Target','Actual']];function add(period,values,code,name,prefix,labels,hidden=[]){labels.forEach((label,i)=>{if(!hidden.includes(i))lines.push([period,code,name,values[`${prefix}-${i}-label`]||label,values[`${prefix}-${i}-target`]||'',values[`${prefix}-${i}-actual`]||''])})}add('Current',dashboard,'','Team dashboard','score',dashboardRows);for(const [code,hp] of hps)add('Current',hp.metrics,code,hp.name,'hp',hpRows,hp.hidden_rows||[]);for(const report of window.reportHistory||[]){add(report.period_end,report.dashboard_values,'','Team dashboard','score',dashboardRows);for(const hp of report.hp_values||[])add(report.period_end,hp.metrics,hp.code,hp.name,'hp',hpRows,hp.hidden_rows||[])}return lines}
$('downloadReport').addEventListener('click',()=>{const csv=reportRows().map(row=>row.map(csvCell).join(',')).join('\r\n'),link=document.createElement('a');link.href=URL.createObjectURL(new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8'}));link.download='jiha-team-report.csv';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)});
$('printReport').addEventListener('click',()=>{const section=$('printData'),heading=document.createElement('h1'),table=document.createElement('table');heading.textContent='Jiha Team Report';section.replaceChildren(heading);for(const [index,row] of reportRows().entries()){const tr=document.createElement('tr');for(const value of row){const cell=document.createElement(index?'td':'th');cell.textContent=value;tr.append(cell)}table.append(tr)}section.append(table);window.print()});
$('today').textContent=new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'long',year:'numeric'}).format(new Date());renderDashboard();renderHpSelect();renderScoreboard();api('me').then(({user,needsSetup})=>showSession(user,needsSetup)).catch(error=>message('authMessage',error.message,'error'));
